    var rows = reg.map(function (r) { return '<tr><th>' + esc(lx(STN[DI[r[0]].st])) + ' · ' + esc(dn(r[0]).split(' · ').pop()) + '</th>' + ['visit', 'quiz', 'sim'].map(function (k) { return '<td>' + (r[1].indexOf(k) >= 0 ? stampSvg(P.stamps[r[0] + '.' + k]) : '') + '</td>'; }).join('') + '</tr>'; }).join('');
